#!/usr/bin/env python3
"""Actual conversion/cache policy with recording Android adapters backed by ImageIO."""
from pathlib import Path
import tempfile,subprocess
repo=Path(__file__).resolve().parents[3];r=Path(tempfile.mkdtemp(prefix='snarty-portraits-'))
sources={
'android/graphics/Bitmap.java':'''package android.graphics;import java.awt.image.*;import java.io.*;import javax.imageio.*;public class Bitmap{BufferedImage b;Bitmap(BufferedImage i){b=i;}public enum Config{RGB_565}public enum CompressFormat{JPEG}public static Bitmap createBitmap(int w,int h,Config c){return new Bitmap(new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB));}public int getWidth(){return b.getWidth();}public int getHeight(){return b.getHeight();}public boolean compress(CompressFormat f,int q,OutputStream s)throws IOException{return ImageIO.write(b,"jpg",s);}public void recycle(){}}''',
'android/graphics/BitmapFactory.java':'''package android.graphics;import java.io.*;import java.awt.image.*;import javax.imageio.*;public class BitmapFactory{public static class Options{public boolean inJustDecodeBounds;public int outWidth,outHeight,inSampleSize=1;}public static Bitmap decodeFile(String p,Options o){try{BufferedImage b=ImageIO.read(new File(p));if(b==null)return null;o.outWidth=b.getWidth();o.outHeight=b.getHeight();return o.inJustDecodeBounds?null:new Bitmap(b);}catch(IOException e){return null;}}}''',
'android/graphics/Canvas.java':'''package android.graphics;public class Canvas{Bitmap b;public Canvas(Bitmap a){b=a;}public void drawBitmap(Bitmap a,Rect s,Rect d,Paint p){java.awt.Graphics2D g=b.b.createGraphics();g.drawImage(a.b,d.a,d.b,d.c,d.d,s.a,s.b,s.c,s.d,null);g.dispose();}}''',
'android/graphics/Rect.java':'package android.graphics;public class Rect{int a,b,c,d;public Rect(int x,int y,int z,int w){a=x;b=y;c=z;d=w;}}',
'android/graphics/Paint.java':'package android.graphics;public class Paint{public static final int FILTER_BITMAP_FLAG=1;public Paint(int flags){}}',
'android/util/Log.java':'package android.util;public class Log{public static void w(String a,String b,Throwable t){}}',
'org/rockbox/ArtistImagesTest.java':'''package org.rockbox;import java.io.*;import java.nio.file.*;import java.awt.*;import java.awt.image.*;import javax.imageio.*;public class ArtistImagesTest{static void check(boolean b){if(!b)throw new AssertionError();}public static void main(String[]a)throws Exception{Path root=Files.createTempDirectory("artist-policy-");File rb=root.resolve(".rockbox").toFile();rb.mkdirs();File source=root.resolve("Artist_Images").toFile();source.mkdirs();BufferedImage im=new BufferedImage(400,200,BufferedImage.TYPE_INT_RGB);Graphics2D g=im.createGraphics();g.setColor(Color.RED);g.fillRect(0,0,200,200);g.setColor(Color.BLUE);g.fillRect(200,0,200,200);g.dispose();File input=new File(source,"Artist A.png");ImageIO.write(im,"png",input);byte[] original=Files.readAllBytes(input.toPath());Files.write(new File(source,"Broken.png").toPath(),new byte[]{1,2,3});RandomAccessFile big=new RandomAccessFile(new File(source,"Huge.png"),"rw");big.setLength(16777217);big.close();ArtistImages.convert(rb);File output=new File(rb,"snarty/artist-images/Artist A.jpg");BufferedImage result=ImageIO.read(output);check(result.getWidth()==200&&result.getHeight()==200);Color left=new Color(result.getRGB(20,100)),right=new Color(result.getRGB(180,100));check(left.getRed()>180&&right.getBlue()>180);check(java.util.Arrays.equals(original,Files.readAllBytes(input.toPath())));check(!new File(output.getParent(),"Broken.jpg").exists());check(!new File(output.getParent(),"Huge.jpg").exists());long stamp=output.lastModified();ArtistImages.convert(rb);check(output.lastModified()==stamp);input.setLastModified(input.lastModified()+4000);ArtistImages.convert(rb);check(output.lastModified()==input.lastModified());System.out.println("PASS: actual Artist_Images cache conversion center-crops to200x200 JPEG, retains artist names/source bytes, skips corrupt/oversized images, caches unchanged files and refreshes changed timestamps");}}'''}
for n,s in sources.items():p=r/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
subprocess.run(['javac','-d',str(r),*[str(r/n) for n in sources],str(repo/'android/y1/src/org/rockbox/ArtistImages.java')],check=True)
subprocess.run(['java','-Djava.awt.headless=true','-cp',str(r),'org.rockbox.ArtistImagesTest'],check=True)
